import { useState, useEffect } from 'react';
import io from 'socket.io-client';

const useSocket = (navigate, userVideo, setStream, setIsHosting, setIsJoined) => {
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const newSocket = io.connect('http://localhost:3001');
    setSocket(newSocket);

    newSocket.on('host', () => {
      setIsHosting(true);
      navigate('/meeting', {
        state: {
          isMicEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getAudioTracks()[0].enabled,
          isCamEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getVideoTracks()[0].enabled
        }
      });
    });

    newSocket.on('join', () => {
      setIsJoined(true);
      navigate('/meeting', {
        state: {
          isMicEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getAudioTracks()[0].enabled,
          isCamEnabled: userVideo.current.srcObject && userVideo.current.srcObject.getVideoTracks()[0].enabled
        }
      });
    });

    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(stream => {
        userVideo.current.srcObject = stream;
        setStream(stream);
      })
      .catch(err => {
        console.error('Error accessing media devices.', err);
      });

    return () => newSocket.close();
  }, [navigate, setStream, setIsHosting, setIsJoined, userVideo]);

  return socket;
};

export default useSocket;
